// The catalogue of apps Settings › Connections lists: `Resources/composio-catalog.json` (generated by tools/composio;
// about a thousand apps with their categories), decoded once on first use. Without a readable resource the catalogue
// is the eight apps of `ComposioApps.known` in one "Popular" category. The bundled file is the curated snapshot
// (hand-written summaries, our categories, the popular ranks, bundled logos). `shared` is what the page shows: the
// bundled catalogue merged with the list of apps the relay says exist right now (`LiveAppCatalog`, which posts
// `DirectoryCatalogs.didChange` when that list changes), or the bundled one alone.
import Foundation

public struct ComposioCatalog: Sendable {
    public struct Category: Sendable, Equatable, Decodable, Identifiable {
        public let id: String
        public let title: String
        public init(id: String, title: String) { self.id = id; self.title = title }
    }

    public struct App: Sendable, Equatable, Decodable, Identifiable {
        /// The Composio toolkit slug the relay links (`gmail`).
        public let slug: String
        public let name: String
        /// One line saying what the app is for ("" = none).
        public let summary: String
        public let categories: [String]
        /// The rank among the popular apps (1 = first); nil = not one of them.
        public let popular: Int?
        /// Where the logo of an app this build has no logo for is loaded from (Composio's logo host, as the relay
        /// listed it); nil for every bundled app and for an app without one (the initial shows).
        public let logoURL: URL?
        public var id: String { slug }

        enum CodingKeys: String, CodingKey { case slug, name, summary, categories, popular }

        public init(slug: String, name: String, summary: String = "", categories: [String] = [], popular: Int? = nil,
                    logoURL: URL? = nil) {
            self.slug = slug; self.name = name; self.summary = summary; self.categories = categories; self.popular = popular
            self.logoURL = logoURL
        }

        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            slug = try c.decode(String.self, forKey: .slug)
            name = try c.decodeIfPresent(String.self, forKey: .name) ?? slug.capitalized
            summary = try c.decodeIfPresent(String.self, forKey: .summary) ?? ""
            categories = try c.decodeIfPresent([String].self, forKey: .categories) ?? []
            popular = try? c.decodeIfPresent(Int.self, forKey: .popular)
            logoURL = nil
        }
    }

    /// The day the catalogue was generated (`2026-11-16`); "" = unknown (the built-in eight apps).
    public let generated: String
    /// In display order.
    public let categories: [Category]
    /// Popular apps first (by rank), then by name.
    public let apps: [App]
    /// Composio's category names (lowercase) → our category ids, for an app the bundled catalogue does not have.
    public let categoryMap: [String: String]
    /// Slugs never shown although Composio lists them (duplicates, developer plumbing).
    public let excluded: Set<String>
    private let bySlug: [String: Int]
    /// What a person may call an app (its name, its slug; `ComposioApps.normalized`) → its slug.
    private let byName: [String: String]
    /// Per app, what `search` matches: name, slug and summary, folded.
    private let keys: [(name: String, rest: String)]

    /// The catalogue this build ships.
    public static let bundled = ComposioCatalog(data: Bundle.module.url(forResource: "composio-catalog", withExtension: "json")
        .flatMap { try? Data(contentsOf: $0) })

    /// What the directory shows: `bundled` merged with the relay's live list of apps, else `bundled`.
    public static var shared: ComposioCatalog { LiveAppCatalog.live?.catalog ?? bundled }

    /// `data` = the JSON file; nil or unreadable = the built-in eight apps.
    public init(data: Data?) {
        struct File: Decodable {
            let generated: String?; let categories: [Category]; let apps: [App]
            let category_map: [String: String]?; let exclude: [String]?
        }
        if let data, let f = try? JSONDecoder().decode(File.self, from: data), !f.apps.isEmpty {
            self.init(categories: f.categories, apps: f.apps, generated: f.generated ?? "",
                      categoryMap: f.category_map ?? [:], excluded: Set(f.exclude ?? []))
        } else {
            self.init(categories: [Category(id: "popular", title: "Popular")],
                      apps: ComposioApps.known.enumerated().map { App(slug: $1.slug, name: $1.title, categories: ["popular"], popular: $0 + 1) })
        }
    }

    public init(categories: [Category], apps: [App], generated: String = "", categoryMap: [String: String] = [:],
                excluded: Set<String> = []) {
        self.generated = generated
        self.categoryMap = categoryMap
        self.excluded = excluded
        let sorted = apps.sorted {
            ($0.popular ?? .max, Self.fold($0.name), $0.slug) < ($1.popular ?? .max, Self.fold($1.name), $1.slug)
        }
        self.categories = categories
        self.apps = sorted
        bySlug = Dictionary(sorted.enumerated().map { ($1.slug, $0) }, uniquingKeysWith: { a, _ in a })
        var names: [String: String] = [:]
        for a in sorted {
            for n in [a.name, a.slug, a.slug.replacingOccurrences(of: "_", with: "")] {
                let k = ComposioApps.normalized(n)
                if !k.isEmpty, names[k] == nil { names[k] = a.slug }
            }
        }
        byName = names
        keys = sorted.map { (Self.fold($0.name), Self.fold($0.slug + " " + $0.summary)) }
    }

    public func app(_ slug: String) -> App? { bySlug[slug].map { apps[$0] } }

    /// The app called exactly `name` ("Trello", "google sheets", "googlesheets"); popular apps win a shared name.
    public func slug(named name: String) -> String? { byName[ComposioApps.normalized(name)] }

    /// The apps of a category, in catalogue order.
    public func apps(in category: String) -> [App] { apps.filter { $0.categories.contains(category) } }

    /// The apps whose name, slug or summary contains `query` (case and accents ignored): names that start with it
    /// first, then names that contain it, then the rest; popular apps first within each. An empty query = no apps.
    public func search(_ query: String) -> [App] {
        let q = Self.fold(query.trimmingCharacters(in: .whitespacesAndNewlines))
        guard !q.isEmpty else { return [] }
        var tiers: [[App]] = [[], [], []]
        for (i, k) in keys.enumerated() {
            if k.name.hasPrefix(q) { tiers[0].append(apps[i]) }
            else if k.name.contains(q) { tiers[1].append(apps[i]) }
            else if k.rest.contains(q) { tiers[2].append(apps[i]) }
        }
        return tiers.flatMap { $0 }
    }

    static func fold(_ s: String) -> String {
        s.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en"))
    }
}
